import os
import inspect
from datetime import datetime, timedelta
from functools import wraps


def ignore_exception(fun, exception=KeyError):
    @wraps(fun)
    def wrapper(*args, **kwargs):
        try:
            result = fun(*args, **kwargs)
            return result
        except exception:
            pass

    return wrapper


class ClassProperty(object):
    def __init__(self, method):
        self.method = classmethod(method)

    def __get__(self, *args):
        return self.method.__get__(*args)()


def get_default_args(func):
    """
    Returns a dictionary of arg_name:default_values for the input function
    """
    args, varargs, keywords, defaults = inspect.getargspec(func)
    return dict(zip(args[-len(defaults):], defaults))


def get_defined_kwargs(**kwargs):
    defined_kwargs = {}
    for arg_name in kwargs:
        if kwargs[arg_name]:
            defined_kwargs[arg_name] = kwargs[arg_name]

    return defined_kwargs


def get_library_path():
    current_dir = os.path.dirname(os.path.abspath(__file__))
    library_path = os.path.abspath(os.path.join(current_dir, '..'))
    return library_path


def prepare_event_message(event):
    result = event.get_last_occurrence()
    _time = round_time_to_seconds(datetime.strptime(str(result['time']), "%Y-%m-%d %H:%M:%S.%f"))
    msg = "Detected '{}' on [{}] at [{}]".format(result['matched'], event.connection.name, _time)

    return msg


def round_time_to_seconds(dt):
    round_sec = 0
    microseconds = 0
    if isinstance(dt, datetime):
        microseconds = dt.microsecond
    elif isinstance(dt, timedelta):
        microseconds = dt.microseconds

    if microseconds > 500000:
        round_sec = 1
    rounded = dt - timedelta(microseconds=microseconds) + timedelta(seconds=round_sec)
    return rounded
